import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.BrO6lPIi.js";const h=JSON.parse('{"title":"文档图像识别系统","description":"本系统为 AI Helper 扩展的“文档图像识别”能力，目标是在用户上传 Word、PDF、Excel 等文档后，把文档内嵌图片转述为文本送入主模型对话；同时提供 `read_document_image`（现泛化为 `read_image`）工具，让 Agent 按需深读某张图。","frontmatter":{"title":"文档图像识别系统","description":"本系统为 AI Helper 扩展的“文档图像识别”能力，目标是在用户上传 Word、PDF、Excel 等文档后，把文档内嵌图片转述为文本送入主模型对话；同时提供 `read_document_image`（现泛化为 `read_image`）工具，让 Agent 按需深读某张图。"},"headers":[],"relativePath":"系统架构设计/数据流设计/RAG-数据处理管道/文档图像识别系统/index.md","filePath":"系统架构设计/数据流设计/RAG-数据处理管道/文档图像识别系统/index.md","lastUpdated":null}'),o={name:"系统架构设计/数据流设计/RAG-数据处理管道/文档图像识别系统/index.md"};function n(s,e,l,c,d,g){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="文档图像识别系统" tabindex="-1">文档图像识别系统 <a class="header-anchor" href="#文档图像识别系统" aria-label="Permalink to &quot;文档图像识别系统&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json" target="_blank" rel="noreferrer">package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json" target="_blank" rel="noreferrer">agent/package.json</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js" target="_blank" rel="noreferrer">src/side_panel/doc-images.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/image-extractor.js" target="_blank" rel="noreferrer">agent/src/documents/image-extractor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/zip-reader.js" target="_blank" rel="noreferrer">agent/src/documents/zip-reader.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js" target="_blank" rel="noreferrer">agent/src/documents/routes.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/doc-images-extract.unit.test.js" target="_blank" rel="noreferrer">test/unit/doc-images-extract.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/plans/2026-10-22-document-image-recognition.md" target="_blank" rel="noreferrer">docs/superpowers/plans/2026-10-22-document-image-recognition.md</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构定位">项目结构定位</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源控制">性能与资源控制</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本系统为 AI Helper 扩展的“文档图像识别”能力，目标是在用户上传 Word、PDF、Excel 等文档后，把文档内嵌图片转述为文本送入主模型对话；同时提供 <code>read_document_image</code>（现泛化为 <code>read_image</code>）工具，让 Agent 按需深读某张图。其关键设计是：主模型始终消费纯文本，视觉模型仅在插件端调用；Agent 端只负责 docx 抽图落盘和按需提供下载，不解析 PDF，也不接触任何模型调用。</p><p>该功能由规划与设计文档确认，并在扩展侧与代理侧分别实现：</p><ul><li>扩展侧：浏览器端抽取 docx/pdf/xlsx 图片、压缩、视觉转述、清单块生成、session 级快照中转。</li><li>代理侧：基于 Node ESM 的最小 ZIP 读取器 + docx 图片提取 + <code>/api/documents/extract-images</code> 接口。</li><li>工具层：background 执行 <code>read_image</code>，从 <code>_docImageSnapshot</code> 取图并调用视觉 API。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/README.zh-CN.md#L39-L86" target="_blank" rel="noreferrer">README.zh-CN.md#L39-L86</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L1-L25" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L1-L25</a></li></ul><h2 id="项目结构定位" tabindex="-1">项目结构定位 <a class="header-anchor" href="#项目结构定位" aria-label="Permalink to &quot;项目结构定位&quot;">​</a></h2><p>文档图像识别横跨两个进程：</p><ul><li>Chrome 扩展端（Manifest V3，src/ 目录），版本以仓库根 package.json 为准。</li><li>独立本地代理端 Agent（Node.js，agent/src/server.js 入口），npm 包名 ai-helper-agent，版本以 agent/package.json 为准。</li></ul><pre class="mermaid">graph TB
A[&quot;Chrome 扩展&lt;br/&gt;src/side_panel/doc-images.js&quot;] --&gt; B[&quot;background 工具执行器&lt;br/&gt;read_image 工具&quot;]
B --&gt; C[&quot;chrome.storage.local&lt;br/&gt;_docImageSnapshot&quot;]
B --&gt; D[&quot;视觉模型 API&lt;br/&gt;imageApiBase / imageApiKey / imageModelName&quot;]
A --&gt; E[&quot;浏览器 pdf.js / jszip&quot;]
B --&gt; F[&quot;Agent 文件服务&lt;br/&gt;local-agent-client.downloadFile&quot;]
F --&gt; G[&quot;Agent 文档处理&lt;br/&gt;/api/documents/extract-images&quot;]
G --&gt; H[&quot;agent/src/documents/*&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L44-L51" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L44-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L563-L621" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L563-L621</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L10-L72" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L10-L72</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L109-L183" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L109-L183</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L1-L10" target="_blank" rel="noreferrer">package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L1-L10" target="_blank" rel="noreferrer">agent/package.json#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L7-L25" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L7-L25</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><p>本节聚焦四个关键模块及其职责边界。</p><table tabindex="0"><thead><tr><th>组件</th><th>位置</th><th>主要职责</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>浏览器端文档抠图</td><td><code>src/side_panel/doc-images.js</code></td><td>从 docx/pdf/xlsx 中抽取图片、压缩、视觉转述、构建清单块、写入 session 快照</td><td>File 对象、配置、可选依赖注入</td><td>images 数组、truncated/skipped、dataUrl、预览文案</td></tr><tr><td>代理端 ZIP 读取器</td><td><code>agent/src/documents/zip-reader.js</code></td><td>零依赖解析 ZIP 中央目录，支持 stored/deflate</td><td>Uint8Array Buffer</td><td>条目名列表、指定条目原始字节</td></tr><tr><td>代理端 docx 图片提取</td><td><code>agent/src/documents/image-extractor.js</code></td><td>按 document.xml r:embed 顺序抽取 PNG/JPEG/GIF/BMP/WebP</td><td>docx 字节缓冲</td><td>images、truncated、skipped</td></tr><tr><td>代理端文档接口</td><td><code>agent/src/documents/routes.js</code></td><td>校验路径、限制大小、解析 zip、落盘 <code>_attachments/&lt;词干&gt;/</code>、写 manifest</td><td><code>{ path, maxImages? }</code></td><td><code>{ success, dir, images, truncated, skipped }</code></td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L87-L138" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L87-L138</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L152-L252" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L152-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L320-L405" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L320-L405</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/zip-reader.js#L1-L83" target="_blank" rel="noreferrer">agent/src/documents/zip-reader.js#L1-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/image-extractor.js#L1-L89" target="_blank" rel="noreferrer">agent/src/documents/image-extractor.js#L1-L89</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L1-L73" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L1-L73</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>文档图像识别的整体数据流分为三个阶段：附件上传阶段、会话快照阶段、工具深读阶段。</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant Panel as &quot;侧边栏附件处理&quot;
participant DocImg as &quot;doc-images.js&quot;
participant Storage as &quot;chrome.storage.local&quot;
participant BG as &quot;background 工具执行器&quot;
participant Vision as &quot;视觉模型 API&quot;
participant Agent as &quot;Agent 文件服务&quot;
User-&gt;&gt;Panel : &quot;上传 docx/pdf/xlsx&quot;
Panel-&gt;&gt;DocImg : &quot;extractDocxImagesFromFile / extractPdfImagesFromFile / extractXlsxImagesFromFile&quot;
DocImg--&gt;&gt;Panel : &quot;{ images, truncated, skipped }&quot;
Panel-&gt;&gt;DocImg : &quot;describeImages(前 N 张)&quot;
DocImg-&gt;&gt;Vision : &quot;chat/completions(图片+OCR提示)&quot;
Vision--&gt;&gt;DocImg : &quot;描述文本或空&quot;
Panel-&gt;&gt;Storage : &quot;saveDocImageSnapshot(sessionId, attachedFiles)&quot;
Note over Panel,Storage : &quot;写入 _docImageSnapshot，含 dataUrl 或 path&quot;
BG-&gt;&gt;BG : &quot;executeTool(read_image)&quot;
BG-&gt;&gt;Storage : &quot;读取 _docImageSnapshot[sessionId]&quot;
alt &quot;本地来源 dataUrl 存在&quot;
BG-&gt;&gt;Vision : &quot;压缩后发送图片深读请求&quot;
Vision--&gt;&gt;BG : &quot;返回分析文本&quot;
else &quot;Agent 来源 path 存在&quot;
BG-&gt;&gt;Agent : &quot;downloadFile(path)&quot;
Agent--&gt;&gt;BG : &quot;{ content(base64), mimeType }&quot;
BG-&gt;&gt;Vision : &quot;安全校验后发送深读请求&quot;
Vision--&gt;&gt;BG : &quot;返回分析文本&quot;
end
BG--&gt;&gt;User : &quot;工具结果：成功文本或错误文案&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L448-L501" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L448-L501</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L577-L612" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L577-L612</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L109-L183" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L109-L183</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L14-L25" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L14-L25</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L102-L116" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L102-L116</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="浏览器端文档图片抽取与视觉转述" tabindex="-1">浏览器端文档图片抽取与视觉转述 <a class="header-anchor" href="#浏览器端文档图片抽取与视觉转述" aria-label="Permalink to &quot;浏览器端文档图片抽取与视觉转述&quot;">​</a></h3><p><code>src/side_panel/doc-images.js</code> 是扩展侧的核心模块，承担三类文档的图片抽取与视觉链路。</p><h4 id="设计要点" tabindex="-1">设计要点 <a class="header-anchor" href="#设计要点" aria-label="Permalink to &quot;设计要点&quot;">​</a></h4><ul><li>开关统一复用 <code>state.enableImageInput</code>，不新增配置项。</li><li>尺寸解析算法与 Agent 端 <code>image-extractor.js</code> 同步，避免两端编号不一致。</li><li>docx 使用 JSZip 解析 <code>word/media/*</code>，按 <code>document.xml</code> 中 <code>r:embed</code> 出现顺序编号。</li><li>xlsx 解析 workbook→rels→sheet→drawing→media，记录 sheet 名与单元格坐标。</li><li>pdf 在浏览器端用 pdfjs-dist，优先抓位图，无位图且文本稀少时整页渲染作为扫描件兜底。</li><li>单图压缩采用 5 轮降级：先降 quality，再缩尺寸，仍超则放弃实体但保留清单元信息。</li><li>视觉配置走 <code>imageApiBase/imageApiKey/imageModelName</code>，留空回落基础模型配置。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;开始&quot;]) --&gt; Type{&quot;文档类型&quot;}
Type --&gt; |docx| Docx[&quot;JSZip 解析 word/document.xml 与 rels&quot;]
Type --&gt; |xlsx| Xlsx[&quot;workbook→rels→sheet→drawing→media&quot;]
Type --&gt; |pdf| Pdf[&quot;pdfjs-dist 抓取 paintImageXObject&quot;]
Docx --&gt; Extract[&quot;构造 images 数组&lt;br/&gt;index/page/mimeType/bytes/width/height/dataUrl/kind&quot;]
Xlsx --&gt; Extract
Pdf --&gt; ScanCheck{&quot;是否扫描页候选？&quot;}
ScanCheck --&gt; |是| RenderPage[&quot;OffscreenCanvas 整页渲染 JPEG&quot;]
ScanCheck --&gt; |否| SkipRender[&quot;跳过整页渲染&quot;]
RenderPage --&gt; Extract
SkipRender --&gt; Extract
Extract --&gt; Compress[&quot;compressForVision 五轮降级&quot;]
Compress --&gt; Describe[&quot;describeImages 并发转述前 N 张&quot;]
Describe --&gt; Snapshot[&quot;saveDocImageSnapshot 写入 _docImageSnapshot&quot;]
Snapshot --&gt; End([&quot;结束&quot;])
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L93-L138" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L93-L138</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L161-L252" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L161-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L326-L405" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L326-L405</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L423-L436" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L423-L436</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L455-L501" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L455-L501</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L577-L612" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L577-L612</a></li></ul><h4 id="关键函数说明" tabindex="-1">关键函数说明 <a class="header-anchor" href="#关键函数说明" aria-label="Permalink to &quot;关键函数说明&quot;">​</a></h4><ul><li><code>extractDocxImagesFromFile(file, opts)</code>：浏览器端 docx 抠图，返回 images、truncated、skipped。</li><li><code>extractXlsxImagesFromFile(file, opts)</code>：浏览器端 xlsx 浮动图片抠图，带 sheet 与 cell 定位。</li><li><code>extractPdfImagesFromFile(file, opts, deps)</code>：浏览器端 pdf 抠图，支持位图去重与扫描页渲染。</li><li><code>compressForVision(dataUrl, deps)</code>：将 dataUrl 压缩到视觉上限，失败返回 null。</li><li><code>describeImages(images, count, onEach)</code>：并发调用视觉模型，返回 index→description 映射。</li><li><code>buildImageBlock(fileEntry, fileName)</code>：拼装消息内联图片清单块。</li><li><code>saveDocImageSnapshot(sessionId, attachedFiles)</code>：写入 session 级图片快照，按预算淘汰旧会话。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L44-L51" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L44-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L87-L138" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L87-L138</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L152-L252" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L152-L252</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L320-L405" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L320-L405</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L418-L446" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L418-L446</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L448-L501" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L448-L501</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L508-L525" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L508-L525</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L577-L621" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L577-L621</a></li></ul><h3 id="代理端-zip-读取器与-docx-图片提取" tabindex="-1">代理端 ZIP 读取器与 docx 图片提取 <a class="header-anchor" href="#代理端-zip-读取器与-docx-图片提取" aria-label="Permalink to &quot;代理端 ZIP 读取器与 docx 图片提取&quot;">​</a></h3><p>代理端不引入 jszip，而是通过 <code>node:zlib</code> 实现最小 ZIP 读取器，仅支持 stored 与 deflate。</p><h4 id="zip-读取流程" tabindex="-1">ZIP 读取流程 <a class="header-anchor" href="#zip-读取流程" aria-label="Permalink to &quot;ZIP 读取流程&quot;">​</a></h4><pre class="mermaid">flowchart TD
Input[&quot;Uint8Array Buffer&quot;] --&gt; EOCD[&quot;反向扫描 EOCD 签名&quot;]
EOCD --&gt; Central[&quot;遍历中央目录条目&quot;]
Central --&gt; Match{&quot;名称匹配？&quot;}
Match --&gt; |否| Next[&quot;继续下一个条目&quot;]
Match --&gt; |是| LocalHeader[&quot;解析本地头 nameLen/extraLen&quot;]
LocalHeader --&gt; Method{&quot;压缩方式&quot;}
Method --&gt; |stored| Raw[&quot;直接截取 compSize&quot;]
Method --&gt; |deflate| Inflate[&quot;inflateRawSync 解压&quot;]
Raw --&gt; Output[&quot;返回 Uint8Array&quot;]
Inflate --&gt; Output
Next --&gt; Central
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/zip-reader.js#L14-L41" target="_blank" rel="noreferrer">agent/src/documents/zip-reader.js#L14-L41</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/zip-reader.js#L65-L82" target="_blank" rel="noreferrer">agent/src/documents/zip-reader.js#L65-L82</a></li></ul><h4 id="docx-提取流程" tabindex="-1">docx 提取流程 <a class="header-anchor" href="#docx-提取流程" aria-label="Permalink to &quot;docx 提取流程&quot;">​</a></h4><ul><li>读取 <code>word/document.xml</code> 与 <code>word/_rels/document.xml.rels</code>。</li><li>建立 rId→media 路径映射。</li><li>按 <code>r:embed</code> 出现顺序收集唯一 media 路径。</li><li>对 PNG/JPEG/GIF/BMP/WebP 进行头部尺寸解析，超过单图字节上限跳过。</li><li>返回 images、truncated、skipped。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/zip-reader.js#L1-L83" target="_blank" rel="noreferrer">agent/src/documents/zip-reader.js#L1-L83</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/image-extractor.js#L14-L31" target="_blank" rel="noreferrer">agent/src/documents/image-extractor.js#L14-L31</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/image-extractor.js#L39-L88" target="_blank" rel="noreferrer">agent/src/documents/image-extractor.js#L39-L88</a></li></ul><h3 id="代理端文档接口-api-documents-extract-images" tabindex="-1">代理端文档接口 <code>/api/documents/extract-images</code> <a class="header-anchor" href="#代理端文档接口-api-documents-extract-images" aria-label="Permalink to &quot;代理端文档接口 \`/api/documents/extract-images\`&quot;">​</a></h3><p>该接口用于 Agent 模式下接收 docx 文件并落盘图片。</p><pre class="mermaid">flowchart TD
Req[&quot;POST /api/documents/extract-images&quot;] --&gt; Validate[&quot;校验 path 与扩展名 .docx&quot;]
Validate --&gt; Security[&quot;checkPath 安全检查&quot;]
Security --&gt; Exists{&quot;文件存在且为文件？&quot;}
Exists --&gt; |否| NotFound[&quot;返回 notFound&quot;]
Exists --&gt; Size{&quot;文件大小 ≤ 50MB？&quot;}
Size --&gt; |否| TooLarge[&quot;返回 fileTooLarge&quot;]
Size --&gt; Read[&quot;读取文件字节&quot;]
Read --&gt; ZipCheck[&quot;listEntryNames 预校验 zip 完整性&quot;]
ZipCheck --&gt; Extract[&quot;extractDocxImages(buf, opts)&quot;]
Extract --&gt; WriteDir[&quot;删除并重建 _attachments/&lt;词干&gt;/&quot;]
WriteDir --&gt; WriteFiles[&quot;写入 img-{index}.{ext}&quot;]
WriteFiles --&gt; Manifest[&quot;写入 manifest.json&quot;]
Manifest --&gt; Success[&quot;返回 { success, dir, images, truncated, skipped }&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L16-L72" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L16-L72</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L1-L73" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L1-L73</a></li></ul><h3 id="内置工具-read-image-原-read-document-image" tabindex="-1">内置工具 read_image（原 read_document_image） <a class="header-anchor" href="#内置工具-read-image-原-read-document-image" aria-label="Permalink to &quot;内置工具 read_image（原 read_document_image）&quot;">​</a></h3><p>工具定义与执行逻辑位于 background 工具体系，测试用例明确其行为契约。</p><h4 id="工具行为" tabindex="-1">工具行为 <a class="header-anchor" href="#工具行为" aria-label="Permalink to &quot;工具行为&quot;">​</a></h4><ul><li>参数二选一：<code>{ file, image }</code> 或 <code>{ path }</code>。</li><li>本地来源：从 <code>_docImageSnapshot</code> 中读取 dataUrl。</li><li>Agent 来源：通过 <code>local-agent-client.downloadFile(path)</code> 拉取 base64。</li><li>安全校验：magic bytes 与单图体积上限必须通过。</li><li>视觉调用：复用现有视觉配置链路与压缩逻辑。</li><li>错误文案：包含文件名、可用附件、序号越界、缓存失效、Agent 离线、视觉未配置等。</li></ul><pre class="mermaid">sequenceDiagram
participant Tool as &quot;tool-executor.executeTool&quot;
participant Snap as &quot;_docImageSnapshot&quot;
participant DL as &quot;local-agent-client.downloadFile&quot;
participant Safe as &quot;安全校验&quot;
participant Vision as &quot;视觉模型 API&quot;
Tool-&gt;&gt;Snap : &quot;查找 sessionId 下 files&quot;
alt &quot;file+image 模式&quot;
Tool-&gt;&gt;Snap : &quot;定位 {name, images[index]}&quot;
alt &quot;dataUrl 存在&quot;
Tool-&gt;&gt;Safe : &quot;校验 dataUrl 大小与类型&quot;
else &quot;path 存在&quot;
Tool-&gt;&gt;DL : &quot;downloadFile(path)&quot;
DL--&gt;&gt;Tool : &quot;{ success, content, mimeType }&quot;
Tool-&gt;&gt;Safe : &quot;校验 base64 内容&quot;
end
else &quot;path 模式&quot;
Tool-&gt;&gt;DL : &quot;downloadFile(path)&quot;
DL--&gt;&gt;Tool : &quot;{ success, content, mimeType }&quot;
Tool-&gt;&gt;Safe : &quot;校验 base64 内容&quot;
end
Safe--&gt;&gt;Tool : &quot;通过 → 压缩/直传&quot;
Tool-&gt;&gt;Vision : &quot;chat/completions(图片+问题)&quot;
Vision--&gt;&gt;Tool : &quot;分析文本&quot;
Tool--&gt;&gt;Tool : &quot;返回 { success, content }&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L109-L183" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L109-L183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L185-L259" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L185-L259</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L1-L260" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L1-L260</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L102-L116" target="_blank" rel="noreferrer">docs/superpowers/specs/2026-10-22-document-image-recognition-design.md#L102-L116</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><p>文档图像识别涉及扩展侧与代理侧的多层依赖。</p><pre class="mermaid">graph LR
DPkg[&quot;扩展 package.json&quot;] --&gt; JSZip[&quot;jszip&quot;]
DPkg --&gt; PDFJS[&quot;pdfjs-dist&quot;]
DPkg --&gt; Mammoth[&quot;mammoth&quot;]
APkg[&quot;agent package.json&quot;] --&gt; Zlib[&quot;node:zlib&quot;]
APkg --&gt; WS[&quot;ws&quot;]
APkg --&gt; Archiver[&quot;archiver&quot;]
APkg --&gt; Zod[&quot;zod&quot;]
SidePanel[&quot;src/side_panel/doc-images.js&quot;] --&gt; DPkg
AgentRoutes[&quot;agent/src/documents/routes.js&quot;] --&gt; ImageExt[&quot;agent/src/documents/image-extractor.js&quot;]
ImageExt --&gt; ZipReader[&quot;agent/src/documents/zip-reader.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L43-L50" target="_blank" rel="noreferrer">package.json#L43-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L43" target="_blank" rel="noreferrer">agent/package.json#L26-L43</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L95-L96" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L95-L96</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L5-L6" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L5-L6</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/package.json#L43-L50" target="_blank" rel="noreferrer">package.json#L43-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/package.json#L26-L43" target="_blank" rel="noreferrer">agent/package.json#L26-L43</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L95-L96" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L95-L96</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L5-L6" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L5-L6</a></li></ul><h2 id="性能与资源控制" tabindex="-1">性能与资源控制 <a class="header-anchor" href="#性能与资源控制" aria-label="Permalink to &quot;性能与资源控制&quot;">​</a></h2><p>系统在多个环节设置了阈值与降级策略，防止大文档与大图拖垮浏览器或外部视觉服务。</p><table tabindex="0"><thead><tr><th>控制点</th><th>阈值或策略</th><th>目的</th></tr></thead><tbody><tr><td>单文档图片数量</td><td><code>MAX_IMAGES = 20</code></td><td>限制单文档抠图上限，超出记 truncated</td></tr><tr><td>单图原始字节</td><td><code>MAX_RAW_BYTES = 5MB</code></td><td>跳过过大图片，避免内存爆炸</td></tr><tr><td>单图视觉上限</td><td><code>MAX_IMAGE_BYTES = 200KB</code></td><td>压缩后送视觉模型，降低带宽与 Token</td></tr><tr><td>视觉转述并发</td><td>前 <code>DESCRIBE_LIMIT = 2</code> 张并发</td><td>缩短最坏等待时间</td></tr><tr><td>视觉请求超时</td><td>60s AbortController</td><td>防止外部 API 挂起</td></tr><tr><td>快照预算</td><td><code>SNAPSHOT_BUDGET = 4MB</code></td><td>淘汰旧会话 dataUrl，保当前会话</td></tr><tr><td>Agent 文件上限</td><td><code>EXTRACT_MAX_FILE_BYTES = 50MB</code></td><td>拒绝超大 docx</td></tr><tr><td>PDF 扫描页阈值</td><td><code>SCANNED_PAGE_TEXT_THRESHOLD = 50</code></td><td>文本稀少才整页渲染，减少无效渲染</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L44-L51" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L44-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L423-L436" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L423-L436</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L469-L499" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L469-L499</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L577-L612" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L577-L612</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L8" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L8</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><p>以下是文档图像识别常见问题的定位思路与对应实现依据。</p><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>排查建议</th><th>相关实现</th></tr></thead><tbody><tr><td>上传 docx 后无图片</td><td>ZIP 损坏或无 <code>word/document.xml</code></td><td>检查代理端 parseFailed 错误</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L34-L43" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L34-L43</a></td></tr><tr><td>PDF 图片为空</td><td>位图不可解析或渲染失败</td><td>查看 logger.warn 日志</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L373-L400" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L373-L400</a></td></tr><tr><td>视觉转述失败</td><td>未配置 imageApiBase/imageApiKey</td><td>检查存储配置</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L439-L446" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L439-L446</a></td></tr><tr><td>深读工具报“缓存已失效”</td><td>跨会话或快照被清理</td><td>重新附加文件</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L162-L166" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L162-L166</a></td></tr><tr><td>Agent 模式无法取图</td><td>Agent 离线或 downloadFile 失败</td><td>检查 Agent 连接状态</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L127-L133" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L127-L133</a></td></tr><tr><td>图片过大被拒绝</td><td>超过单图上限或压缩失败</td><td>检查 magic bytes 与体积闸门</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L137-L147" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L137-L147</a></td></tr><tr><td>xlsx 图片顺序异常</td><td>drawing anchor 顺序或 rels 绝对路径</td><td>检查测试 fixture</td><td><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/doc-images-extract.unit.test.js#L84-L167" target="_blank" rel="noreferrer">test/unit/doc-images-extract.unit.test.js#L84-L167</a></td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/documents/routes.js#L34-L43" target="_blank" rel="noreferrer">agent/src/documents/routes.js#L34-L43</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L373-L400" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L373-L400</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/doc-images.js#L439-L446" target="_blank" rel="noreferrer">src/side_panel/doc-images.js#L439-L446</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/tool-read-document-image.unit.test.js#L127-L166" target="_blank" rel="noreferrer">test/unit/tool-read-document-image.unit.test.js#L127-L166</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/doc-images-extract.unit.test.js#L84-L167" target="_blank" rel="noreferrer">test/unit/doc-images-extract.unit.test.js#L84-L167</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>文档图像识别系统以“浏览器端抽取 + Agent 端落盘 + background 工具深读”的分层架构实现，既满足主模型纯文本消费约束，又覆盖 docx、xlsx、pdf 三类常见办公文档。其关键保障包括：</p><ul><li>双端同步的 docx 编号算法与 PNG/JPEG 尺寸解析。</li><li>浏览器端 pdf.js 统一处理，避免 Agent 端 canvas 依赖问题。</li><li>多层阈值控制：图片数量、原始大小、视觉大小、快照预算、Agent 文件大小。</li><li>工具层严格的安全校验：magic bytes、体积上限、参数二选一、视觉配置前置。</li><li>完善的测试覆盖：浏览器端抽取单测与工具行为单测共同保证回归稳定性。</li></ul><p>对于维护者而言，修改 docx 编号或尺寸解析需同时更新扩展侧与代理侧；修改视觉配置或工具参数需同步更新测试用例；Agent 端源码变更后必须重启进程，新接口才生效。</p>`,89)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
